const CACHE='joseki-sage-v2';

const ICON_192 = '';
const ICON_512 = '';

function b64ToResponse(b64, type){
  var bin=atob(b64), buf=new Uint8Array(bin.length);
  for(var i=0;i<bin.length;i++) buf[i]=bin.charCodeAt(i);
  return new Response(buf,{headers:{'Content-Type':type}});
}

self.addEventListener('fetch',function(event){
  var path=new URL(event.request.url).pathname;
  if(path.endsWith('icon-192.png')){ event.respondWith(b64ToResponse(ICON_192,'image/png')); return; }
  if(path.endsWith('icon-512.png')){ event.respondWith(b64ToResponse(ICON_512,'image/png')); return; }
  event.respondWith(
    fetch(event.request).then(function(response){
      var clone=response.clone();
      caches.open(CACHE).then(function(cache){ cache.put(event.request,clone); });
      return response;
    }).catch(function(){
      return caches.match(event.request);
    })
  );
});
